/**
 * Static visual alternative for devices without WebGL, with Save-Data on,
 * or when the 3D scene fails. The images are real renders of the same 3D
 * model (generated by tools/render-fallback.mjs), one per facade, swapped
 * per section so the static page still "turns" the building.
 */
export const FACADES = {
  front: { src: '/fallback/diwan-front.webp', label: 'الواجهة الأمامية' },
  side: { src: '/fallback/diwan-side.webp', label: 'الواجهة الجانبية' },
  back: { src: '/fallback/diwan-back.webp', label: 'الواجهة الخلفية' },
};

export function createFallbackStage({ img, label, reducedMotion }) {
  let currentFacade = 'front';
  let preloaded = false;

  const isStatic = () => document.documentElement.dataset.scene !== 'ready';

  const preload = () => {
    if (preloaded) return;
    preloaded = true;
    for (const key of Object.keys(FACADES)) {
      if (key === 'front') continue;
      const image = new Image();
      image.decoding = 'async';
      image.src = FACADES[key].src;
    }
  };

  const show = (facade) => {
    const entry = FACADES[facade];
    if (!entry || facade === currentFacade || !isStatic()) return;
    currentFacade = facade;
    preload();
    if (label) label.textContent = entry.label;
    if (reducedMotion) {
      img.src = entry.src;
      return;
    }
    img.classList.add('is-swapping');
    window.setTimeout(() => {
      img.src = entry.src;
      img.classList.remove('is-swapping');
    }, 180);
  };

  return { show, preload };
}
